INSERT  IGNORE INTO `question_buggy_path` (`id`, `question_id`, `wrong_answer`, `heuristic_hint`, `error_type`, `knowledge_point_id`, `occurrence_count`, `is_ai_generated`, `created_at`, `updated_at`) VALUES (1,1,'estabilish','注意字母顺序：是 \"establish\" 而不是 \"estabilish\"，结尾是 \"sh\" 不是 \"s\"','SPELLING','1',5,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(2,1,'establishe','动词第三人称单数才加 \"es\"，这里不需要哦','GRAMMAR','2',3,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(3,2,'effect','注意区分 \"affect\"（动词，影响）和 \"effect\"（名词，效果），这里需要动词','VOCABULARY','3',8,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(4,2,'affects','主语是复数 \"they\"，动词不需要加 \"s\"','GRAMMAR','2',4,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(5,3,'a hour','\"hour\" 虽然以字母 \"h\" 开头，但发音以元音音素开头，应该用 \"an\"','ARTICLE','4',12,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(6,3,'an university','\"university\" 虽然以元音字母开头，但发音以辅音音素开头，应该用 \"a\"','ARTICLE','4',6,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(7,4,'go to home','\"home\" 是副词，前面不需要介词 \"to\"，直接说 \"go home\"','PREPOSITION','5',7,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(8,4,'at school','通常说 \"at school\"，你的答案基本正确，检查一下其他部分','PREPOSITION','5',2,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(9,5,'yesterday I go','时间状语是 \"yesterday\"，句子应该使用过去时态','TENSE','6',10,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(10,5,'I am go now','时间状语是 \"now\"，应该用现在进行时态：\"I am going\"','TENSE','6',5,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(11,6,'since three years','\"since\" 后面应该接时间点，时间段应该用 \"for\"：\"for three years\"','PREPOSITION','5',9,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(12,6,'for 2020','\"for\" 后面接时间段，时间点应该用 \"since\"：\"since 2020\"','PREPOSITION','5',4,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(13,7,'informations','\"information\" 是不可数名词，没有复数形式','GRAMMAR','7',6,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(14,7,'advices','\"advice\" 是不可数名词，表达多条建议可以说 \"pieces of advice\"','GRAMMAR','7',3,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(15,8,'he play','主语是第三人称单数 \"he\"，动词需要加 \"s\"','GRAMMAR','2',11,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(16,8,'they plays','主语是复数 \"they\"，动词不需要加 \"s\"','GRAMMAR','2',5,0,'2026-10-17 12:34:38','2026-10-17 12:34:38'),(17,287,'meal.','这个答案不太对哦，再想一想正确的表达方式。','UNKNOWN',NULL,1,1,'2026-10-17 16:56:07','2026-10-17 16:56:07'),(18,295,'discuss','这个答案不太对哦，再想一想正确的表达方式。','UNKNOWN',NULL,1,1,'2026-10-17 17:06:03','2026-10-17 17:06:03');
INSERT  IGNORE INTO `listening_audio` (`id`, `question_id`, `audio_url`, `transcript`, `duration_seconds`, `created_at`, `updated_at`) VALUES (1,464,'/audio/listening-cet4-01.mp3','W: Excuse me, where is the nearest subway station? M: Go straight ahead and turn left at the second crossing. You will see it next to the bank.',38,'2026-10-31 18:53:24','2026-10-31 18:53:24'),(2,465,'/audio/listening-cet4-02.mp3','M: Why were you not at the meeting this morning? W: My train was delayed for almost an hour because of the heavy snow.',42,'2026-10-31 18:53:24','2026-10-31 18:53:24'),(3,466,'/audio/listening-cet6-01.mp3','Online learning gives students flexibility, but it works best when combined with face-to-face teaching. Students still need direct interaction with teachers and classmates.',55,'2026-10-31 18:53:24','2026-10-31 18:53:24'),(4,467,'/audio/listening-cet6-02.mp3','Scientists say bee populations are declining for two main reasons: the widespread use of pesticides and the loss of natural habitat. Both factors make it harder for bees to find food and reproduce.',60,'2026-10-31 18:53:24','2026-10-31 18:53:24');
